return items.map(item => {
  const remitenteEmail =
    item.json.from?.value?.[0]?.address?.toLowerCase().trim() || "";

  let texto = item.json.text || "";

  // Cortar la parte citada del correo original
  texto = texto.split(/\nEl .* escribió:\n/i)[0];

  // Eliminar líneas citadas que empiezan por >
  texto = texto
    .split("\n")
    .filter(line => !line.trim().startsWith(">"))
    .join("\n");

  // Limpiar espacios excesivos
  texto = texto.replace(/\n{3,}/g, "\n\n").trim();

  return {
    json: {
      subject: item.json.subject || "",
      remitente_email: remitenteEmail,
      messageId: item.json.messageId || "",
      inReplyTo: item.json.inReplyTo || "",
      references: item.json.references || "",
      date: item.json.date || "",
      texto_limpio: texto
    }
  };
});

const correos = $items("Code limpiar correo");
const medicos = $items("BD Médicos");

const resultado = [];

for (const correo of correos) {
  const remitente = (correo.json.remitente_email || "").toLowerCase().trim();
  const subject = correo.json.subject || "";
  const inReplyTo = correo.json.inReplyTo || "";

  const asuntoValido = subject.includes("Disponibilidad guardias");
  const hiloValido = inReplyTo !== "";

  const coincidencias = medicos.filter(m => {
    const email = (m.json.email || "").toLowerCase().trim();
    const activo = (m.json.activo || "").toLowerCase().trim();
    return email === remitente && (activo === "sí" || activo === "si");
  });

  if (asuntoValido && hiloValido && coincidencias.length === 1) {
    const medico = coincidencias[0].json;

    resultado.push({
      json: {
        medico_id: medico.medico_id,
        nombre_medico: medico.nombre,
        email_medico: medico.email,
        remitente_email: correo.json.remitente_email,
        subject: correo.json.subject,
        messageId: correo.json.messageId,
        inReplyTo: correo.json.inReplyTo,
        references: correo.json.references,
        date: correo.json.date,
        texto_limpio: correo.json.texto_limpio,
        validado: true
      }
    });
  }
}

return resultado;

const validados = $items("Agrupar correos por médico");

return items.map((item, index) => {
  let raw = item.json.content?.parts?.[0]?.text || "";

  if (!raw) {
    throw new Error(`No se encontró texto en la respuesta de la IA para el item ${index}`);
  }

  raw = raw
    .replace(/```json/gi, "")
    .replace(/```/g, "")
    .trim();

  let parsed;

  try {
    parsed = JSON.parse(raw);
  } catch (e) {
    throw new Error(`La respuesta de la IA no es JSON válido en el item ${index}: ${raw}`);
  }

  const previo = validados[index]?.json || {};

  return {
    json: {
      medico_id: previo.medico_id || "",
      nombre_medico: previo.nombre_medico || "",
      email_medico: previo.email_medico || "",
      remitente_email: previo.remitente_email || "",
      subject: previo.subject || "",
      messageId: previo.messageId || "",
      messageIds: previo.messageIds || [],
      inReplyTo: previo.inReplyTo || "",
      references: previo.references || "",
      date: previo.date || "",
      texto_limpio: previo.texto_limpio || "",
      validado: previo.validado || false,
      correos: previo.correos || [],
      num_correos_agrupados: previo.num_correos_agrupados || 1,

      no_puedo: parsed.no_puedo || [],
      preferiria_librar: parsed.preferiria_librar || [],
      prefiere_guardia: parsed.prefiere_guardia || [],
      dobletes: parsed.dobletes || [],
      rotacion: parsed.rotacion || "",
      rotacion_externa: parsed.rotacion_externa ?? false,
      restricciones: parsed.restricciones || [],
      anio_residencia: parsed.anio_residencia || "",
      objetivo_guardias: parsed.objetivo_guardias ?? null,
      observaciones: parsed.observaciones || "",

      origen_extraccion: "gemini"
    }
  };
});

const nuevos = $items("Transformamos en Json");
const existentes = $items("Comprobar guardados");

// messageId ya guardados
const idsExistentes = new Set(
  existentes
    .map(item => (item.json.messageId || "").trim())
    .filter(Boolean)
);

// solo deja pasar los nuevos
return nuevos.filter(item => {
  const id = (item.json.messageId || "").trim();
  return id && !idsExistentes.has(id);
});

const grupos = new Map();

for (const item of items) {
  const j = item.json;

  const key = String(j.medico_id || j.email_medico || j.remitente_email).trim();

  if (!grupos.has(key)) {
    grupos.set(key, {
      ...j,
      correos: []
    });
  }

  grupos.get(key).correos.push({
    date: j.date || "",
    messageId: j.messageId || "",
    texto_limpio: j.texto_limpio || ""
  });
}

const resultado = [];

for (const grupo of grupos.values()) {
  grupo.correos.sort((a, b) => new Date(a.date) - new Date(b.date));

  grupo.texto_limpio = grupo.correos
    .map((c, index) => {
      return `CORREO ${index + 1} - ${c.date}\n${c.texto_limpio}`;
    })
    .join("\n\n---\n\n");

  grupo.messageIds = grupo.correos.map(c => c.messageId);
  grupo.messageId = grupo.messageIds.join(" | ");
  grupo.num_correos_agrupados = grupo.correos.length;

  resultado.push({ json: grupo });
}

return resultado;

function uniqueSorted(arr) {
  return [...new Set(Array.isArray(arr) ? arr.filter(Boolean) : [])].sort();
}

function onlyValidJuneDates(arr) {
  return uniqueSorted(arr).filter(x => /^2026-06-\d{2}$/.test(String(x)));
}

function subtract(arr, removeSet) {
  return arr.filter(x => !removeSet.has(x));
}

function limpiarRestricciones(restricciones) {
  if (!Array.isArray(restricciones)) return [];

  return restricciones
    .map(r => String(r || "").trim())
    .filter(Boolean)
    .filter(r => {
      const s = r.toLowerCase();

      // Ya está representado por dobletes=[]
      if (s.includes("no desea realizar dobletes")) return false;
      if (s.includes("prefiere no tener dobletes")) return false;
      if (s.includes("preferiría no hacer dobletes")) return false;
      if (s.includes("preferiria no hacer dobletes")) return false;

      // Ya debería estar expandido a fechas
      if (s.includes("miércoles") || s.includes("miercoles")) return false;
      if (s.includes("martes")) return false;
      if (s.includes("jueves")) return false;

      return true;
    });
}

return items.map(item => {
  const j = item.json;

  let no_puedo = onlyValidJuneDates(j.no_puedo);
  let preferiria_librar = onlyValidJuneDates(j.preferiria_librar);
  let prefiere_guardia = onlyValidJuneDates(j.prefiere_guardia);
  let dobletes = onlyValidJuneDates(j.dobletes);

  const setNo = new Set(no_puedo);
  preferiria_librar = subtract(preferiria_librar, setNo);

  const setPrefLib = new Set(preferiria_librar);
  prefiere_guardia = subtract(prefiere_guardia, setNo);
  prefiere_guardia = subtract(prefiere_guardia, setPrefLib);

  const setPrefGuardia = new Set(prefiere_guardia);
  dobletes = subtract(dobletes, setNo);
  dobletes = subtract(dobletes, setPrefLib);

  return {
    json: {
      ...j,
      no_puedo,
      preferiria_librar,
      prefiere_guardia,
      dobletes,
      restricciones: limpiarRestricciones(j.restricciones),
      rotacion_externa: Boolean(j.rotacion_externa),
      objetivo_guardias:
        Number(j.objetivo_guardias) === 4 || Number(j.objetivo_guardias) === 5
          ? Number(j.objetivo_guardias)
          : null
    }
  };
});

function limpiarRestriccionesTexto(s) {
  const texto = String(s || "").toLowerCase();

  if (texto.includes("no acepta dobletes")) return "";
  if (texto.includes("no realizar dobletes")) return "";
  if (texto.includes("prefiero no tener dobletes")) return "";
  if (texto.includes("preferiría no hacer dobletes")) return "";
  if (texto.includes("preferiria no hacer dobletes")) return "";

  return s || "";
}

return items.map(item => {
  const j = item.json;

  // Arrays seguros
  const no_puedo = j.no_puedo || [];
  const preferiria_librar = j.preferiria_librar || [];
  const dobletes_original = j.dobletes || [];

  // Limpiar dobletes inválidos
  const dobletes_limpios = dobletes_original.filter(
    f => !no_puedo.includes(f) && !preferiria_librar.includes(f)
  );

  return {
    json: {
      clave_disponibilidad: `${j.medico_id}_junio_2026`,
      periodo: "junio_2026",

      medico_id: j.medico_id,
      nombre_medico: j.nombre_medico,
      email_medico: j.email_medico,
      remitente_email: j.remitente_email,

      no_puedo: no_puedo.join(", "),
      preferiria_librar: preferiria_librar.join(", "),
      prefiere_guardia: (j.prefiere_guardia || []).join(", "),
      dobletes: dobletes_limpios.join(", "),

      rotacion: j.rotacion || "",
      rotacion_externa: j.rotacion_externa === true ? "sí" : "no",

      restricciones: limpiarRestriccionesTexto(
        (j.restricciones || []).join(" | ")
      ),

      anio_residencia: j.anio_residencia || "",
      objetivo_guardias: j.objetivo_guardias ?? "",

      observaciones: j.observaciones || "",
      origen_extraccion: j.origen_extraccion || "",

      num_correos_agrupados: j.num_correos_agrupados || 1,
      messageIds: Array.isArray(j.messageIds)
        ? j.messageIds.join(" | ")
        : (j.messageIds || ""),

      fecha_ultimo_correo: j.date || "",
      texto_limpio: j.texto_limpio || ""
    }
  };
});
